mapper.select:
select date_format(treatStartTime,"%Y-%m-%d") lastVisitDate, name name, mobile mobile, treatType treatType, employee_name employeeName from ( select treatStartTime, patient_id, name, mobile, CASE WHEN treat_type = 0 THEN '初诊' WHEN treat_type = 1 THEN '复诊' END AS treatType, employee_name, pinyin_name, registered_dentist_id from ( select t1.*,bp.name, bp.mobile ,bp.pinyin_name,be.employee_name from ( select t1.patient_id, t1.org_id, t1.treat_start_time treatStartTime, t1.treat_type, t1.registered_dentist_id from base_treatment_process t1 join (select t2.patient_id ,max(t2.treat_start_time) treatStartTime from base_treatment_process t2 group by t2.patient_id ) s1 on t1.patient_id = s1.patient_id and t1.treat_start_time IS NOT NULL and t1.treat_start_time = s1.treatStartTime ) t1 left join base_patient bp on t1.patient_id = bp.patient_id left join base_employee be on t1.registered_dentist_id = be.user_id
t1.org_id = #{form.orgId}
and DATE_FORMAT(t1.treatStartTime, "%Y-%m-%d") >= DATE_FORMAT(#{form.startDate}, "%Y-%m-%d") and DATE_FORMAT(t1.treatStartTime, "%Y-%m-%d") <= DATE_FORMAT(#{form.endDate}, "%Y-%m-%d")
) t2
concat(IFNULL(name,''),IFNULL(pinyin_name,''),IFNULL(mobile,'')) like concat(concat('%',#{form.combination}),'%')
AND treat_type in
#{treatType}
AND registered_dentist_id in
#{registeredDentistId}
) t3
where 0 = ( select count(*) from base_treatment_process a where a.patient_id = t3.patient_id and DATE_FORMAT(a.appoint_start_time, "%Y-%m-%d") >= DATE_FORMAT(NOW(), "%Y-%m-%d") )
and
0 = ( select count(*) from base_visit_remind a where a.patient_id = t3.patient_id and type = 1 and DATE_FORMAT(time, "%Y-%m-%d") >= DATE_FORMAT(NOW(), "%Y-%m-%d") )

select count(bp.origin_type)
from base_patient bp

   bp.origin_type_name is not null
   and bp.origin_type is not null

    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) =#{form.year}

select
  bp.origin_type originType,
  bp.origin_type_name originTypeName,
  count(bp.origin_type) countType,
  concat( format(count(bp.origin_type) / ${countOriginType} * 100, 2 ),'%') percentage
from base_patient bp

  bp.origin_type_name is not null
  and bp.origin_type is not null

    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) = #{form.year}


group by  bp.origin_type

select count(bp.gender)
from base_patient bp

  bp.gender is not null

    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) =#{form.year}

 select
  case when bp.gender = 0 then '男'
       when bp.gender = 1 then '女'
  end gender,
  count(bp.gender) countGender,
  concat( format(count(bp.gender) / ${countGender} * 100, 2 ),'%') percentage
from base_patient bp

  bp.gender is not null

    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) =#{form.year}


group by bp.gender

select count(1) from base_patient bp

  bp.birthday is not null

    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) =#{form.year}

select count(1) from base_patient bp

  bp.birthday is not null

    AND bp.org_id = #{form.orgId}



    AND ( DATE_FORMAT(now(),'%Y-%m-%d') - DATE_FORMAT(bp.birthday,'%Y-%m-%d') ) <= #{ageOne}



     AND ( DATE_FORMAT(now(),'%Y-%m-%d') - DATE_FORMAT(bp.birthday,'%Y-%m-%d') ) >= #{ageTwo}



    AND ( DATE_FORMAT(now(),'%Y-%m') - DATE_FORMAT(bp.birthday,'%Y-%m') ) <= #{ageThree}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) =#{form.year}
